class Solution {
    struct DSU{
        vector<int> parent,rank;
        DSU(int n):parent(n),rank(n){
            iota(parent.begin(),parent.end(),0);
        }
        int find(int x){
            return parent[x]==x?x:parent[x]=find(parent[x]);
        }
        bool unite(int a,int b){
            a=find(a);
            b=find(b);
            if(a==b)return false;
            if(rank[a]<rank[b])swap(a,b);
            parent[b]=a;
            if(rank[a]==rank[b])++rank[a];
            return true;
        }
    };
    int n;
    vector<array<int,4>> edges;
    long long mst(int skip,int force){
        DSU dsu(n);
        long long weight=0;
        int used=0;
        if(force!=-1)for(auto edge:edges)if(edge[3]==force){
            if(dsu.unite(edge[0],edge[1])){
                weight+=edge[2];
                ++used;
            }
            break;
        }
        for(auto edge:edges){
            if(edge[3]==skip||edge[3]==force)continue;
            if(dsu.unite(edge[0],edge[1])){
                weight+=edge[2];
                if(++used==n-1)break;
            }
        }
        return used==n-1?weight:LLONG_MAX/4;
    }
    public:vector<vector<int>> findCriticalAndPseudoCriticalEdges(int n,vector<vector<int>>& input){
        this->n=n;
        for(int i=0;i<(int)input.size();++i)edges.push_back({
            input[i][0],input[i][1],input[i][2],i
        });
        sort(edges.begin(),edges.end(),[](auto a,auto b){
            return a[2]<b[2];
        });
        long long base=mst(-1,-1);
        vector<vector<int>> answer(2);
        for(int index=0;index<(int)input.size();++index)if(mst(index,-1)>base)answer[0].push_back(index);
        else if(mst(-1,index)==base)answer[1].push_back(index);
        return answer;
    }
};
